package com.sathavahana.kalamkari.service; import com.sathavahana.kalamkari.domain.User; import com.sathavahana.kalamkari.repository.UserRepository; import jakarta.servlet.http.HttpServletRequest; import org.springframework.stereotype.Component;
@Component public class CurrentUser {private final UserRepository users; private final HttpServletRequest request; public CurrentUser(UserRepository u,HttpServletRequest r){users=u;request=r;} public User require(){String id=request.getHeader("X-User-Id"); if(id==null) throw new IllegalArgumentException("X-User-Id header is required"); try{return users.findById(Long.valueOf(id)).orElseThrow(()->new NotFoundException("User not found"));}catch(NumberFormatException e){throw new IllegalArgumentException("X-User-Id must be numeric");}}}
